  public static FaceTemplate ReadTemplate(){
   string path=AssetDatabase.FindAssets("FaceTemplate t:TextAsset").Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>p.EndsWith("/FaceGeneratorData/FaceTemplate.json",StringComparison.Ordinal));
   if(path==null)throw new FileNotFoundException("FaceGeneratorData/FaceTemplate.json is missing. Copy the FaceGeneratorData folder into Assets alongside the Entity Studio scripts.");
   var asset=AssetDatabase.LoadAssetAtPath<TextAsset>(path);var data=JsonUtility.FromJson<FaceTemplate>(asset.text);using(var sha=System.Security.Cryptography.SHA256.Create())data.contentHash=BitConverter.ToString(sha.ComputeHash(asset.bytes)).Replace("-","").ToLowerInvariant();
   if(data==null||data.version!=1||data.positions==null||data.controls==null||data.morphs==null||data.presets==null)throw new InvalidDataException("Invalid face template data.");string extendedPath=Path.GetDirectoryName(path).Replace('\\','/')+"/FaceExtendedControls.json";var extendedAsset=AssetDatabase.LoadAssetAtPath<TextAsset>(extendedPath);if(extendedAsset!=null){var extended=JsonUtility.FromJson<FaceExtendedData>(extendedAsset.text);if(extended.sourceCommit!=data.sourceCommit)throw new InvalidDataException("Extended targets use a different source revision.");data.extensionCompatibleHashes=extended.compatibleHashes;data.controls=data.controls.Concat(extended.controls).ToArray();data.morphs=data.morphs.Concat(extended.morphs.Where(m=>!data.morphs.Any(existing=>existing.id==m.id))).ToArray();using(var sha=System.Security.Cryptography.SHA256.Create())data.extensionHash=BitConverter.ToString(sha.ComputeHash(extendedAsset.bytes)).Replace("-","").ToLowerInvariant();}string oralPath=Path.GetDirectoryName(path).Replace('\\','/')+"/OralTemplate.json";var oral=AssetDatabase.LoadAssetAtPath<TextAsset>(oralPath);if(oral!=null){data.oral=JsonUtility.FromJson<FaceOralData>(oral.text);using(var sha=System.Security.Cryptography.SHA256.Create())data.oralHash=BitConverter.ToString(sha.ComputeHash(oral.bytes)).Replace("-","").ToLowerInvariant();}string eyePath=Path.GetDirectoryName(path).Replace('\\','/')+"/EyeSurfaceTemplate.json";var eyeAsset=AssetDatabase.LoadAssetAtPath<TextAsset>(eyePath);if(eyeAsset!=null){var eyeData=JsonUtility.FromJson<FaceOralData>(eyeAsset.text);data.eyeSurface=eyeData.meshes.FirstOrDefault();data.eyeCompatibleHashes=eyeData.compatibleHashes;using(var sha=System.Security.Cryptography.SHA256.Create())data.eyeHash=BitConverter.ToString(sha.ComputeHash(eyeAsset.bytes)).Replace("-","").ToLowerInvariant();}RebirthFaceIdentity.Attach(data,Path.GetDirectoryName(path).Replace('\\','/'));return data;
  }
  public static Material[] CreateOralMaterials(FaceRecipe recipe=null){return new[]{"TeethFoundation","TongueFoundation","MouthLining"}.Select(name=>{if(name=="MouthLining"){if(recipe!=null&&recipe.mouthLiningVersion==1&&!string.IsNullOrEmpty(recipe.generatedLiningMaterialGuid)){var savedLining=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(recipe.generatedLiningMaterialGuid));if(savedLining!=null)return new Material(savedLining){hideFlags=HideFlags.HideAndDontSave};}var lining=new Material(Shader.Find("Standard")){name="MouthLining",hideFlags=HideFlags.HideAndDontSave};lining.color=Color.white*.55f;string gumPath=AssetDatabase.FindAssets("TeethFoundation t:Texture2D").Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>p.EndsWith("/FaceGeneratorData/TeethFoundation.png",StringComparison.Ordinal));if(gumPath!=null)lining.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(gumPath);bool packed=recipe!=null&&recipe.highDefinitionUv;var tiling=packed?new Vector2(.20f/.18f,.10f/.26f):new Vector2(.20f/.19f,.10f/.14f);var origin=packed?new Vector2(.80f,.02f):new Vector2(.75f,0);lining.mainTextureScale=tiling;lining.mainTextureOffset=new Vector2(.05f,.45f)-Vector2.Scale(origin,tiling);lining.SetFloat("_Glossiness",.05f);lining.SetFloat("_SpecularHighlights",0);lining.SetFloat("_GlossyReflections",0);lining.EnableKeyword("_SPECULARHIGHLIGHTS_OFF");lining.EnableKeyword("_GLOSSYREFLECTIONS_OFF");return lining;}if(name=="TeethFoundation"&&recipe!=null&&!string.IsNullOrEmpty(recipe.generatedToothMaterialGuid)){var saved=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(recipe.generatedToothMaterialGuid));if(saved!=null){var generated=new Material(saved){hideFlags=HideFlags.HideAndDontSave};generated.color=Color.white*(recipe.toothBrightness/.65f);return generated;}}string path=AssetDatabase.FindAssets(name+" t:Texture2D").Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>p.EndsWith("/FaceGeneratorData/"+name+".png",StringComparison.Ordinal));var mat=new Material(Shader.Find("Standard")){name=name,hideFlags=HideFlags.HideAndDontSave};mat.mainTexture=path==null?null:AssetDatabase.LoadAssetAtPath<Texture2D>(path);mat.color=name.StartsWith("Teeth")?new Color(.65f,.60f,.43f)*(recipe==null?1:recipe.toothBrightness/.65f):new Color(.5f,.35f,.35f);mat.SetFloat("_Glossiness",.22f);return mat;}).Select((m,i)=>{RebirthFaceBlood.Apply(m,recipe,i+1);return m;}).ToArray();}
  public static void DrawOral(PreviewRenderUtility preview,Mesh mesh,Material[] materials){for(int i=2;i<mesh.subMeshCount;i++)RebirthNativePreviewLighting.Draw(preview,mesh,Matrix4x4.identity,materials[i-2],i);}
  void LoadTemplate(){try{template=ReadTemplate();if(recipe==null)recipe=FaceRecipe.FromPreset(template,0);recipe.Validate(template);Rebuild();status="";}catch(Exception e){status=e.Message;}}
  void Rebuild(){hairGeometryQueued=false;if(template==null||recipe==null)return;Mesh next=null,nextHair=null;Material[] nextHairMaterials=null;FacialHairResult nextFacial=null;try{recipe.Validate(template);next=RebirthFaceGeneratorModel.Build(template,recipe);nextHair=RebirthHairGenerator.Build(next,recipe.hair,template,recipe);nextHairMaterials=RebirthHairGenerator.HasHair(recipe)?RebirthHairGenerator.Materials(recipe.hair,recipe):null;if(recipe.nativeAppearance.enabled)nextFacial=RebirthNativeAppearanceLibrary.Facial(next,recipe.nativeAppearance);else nextFacial=RebirthFacialHairGenerator.Build(template,recipe);if(mesh!=null)DestroyImmediate(mesh);if(hairMesh!=null)DestroyImmediate(hairMesh);if(hairMaterials!=null)ReleaseHairMaterials(hairMaterials);facialHair?.Dispose();mesh=next;hairMesh=nextHair;hairMaterials=nextHairMaterials;facialHair=nextFacial;next=null;nextHair=null;nextHairMaterials=null;nextFacial=null;RefreshMaterial();if(framedAll)FrameAll();}catch(Exception e){if(next!=null)DestroyImmediate(next);if(nextHair!=null)DestroyImmediate(nextHair);if(nextHairMaterials!=null)ReleaseHairMaterials(nextHairMaterials);nextFacial?.Dispose();status="Preview update failed: "+e.Message;}}
  void RefreshMaterial(){if(oralMaterials!=null){foreach(var oral in oralMaterials)DestroyImmediate(oral);oralMaterials=null;}if(material!=null)DestroyImmediate(material);material=referenceMaterial!=null?new Material(referenceMaterial):new Material(Shader.Find("Standard"));material.hideFlags=HideFlags.HideAndDontSave;if(referenceMaterial!=null){material.SetFloat("_BumpScale",recipe.poreDetail);material.SetFloat("_GlossMapScale",recipe.skinSmoothness/(65f/255f));}if(referenceMaterial==null){if(recipe.skin.foundation)RebirthFaceAppearance.FoundationSkin(material,recipe.skin);else{material.color=clayColor;material.SetFloat("_Glossiness",.18f);}}RebirthFaceAppearance.ApplySkin(material,recipe);if(eyeMaterial!=null)DestroyImmediate(eyeMaterial);eyeMaterial=RebirthFaceAppearance.EyeMaterial(recipe);eyeMaterial.hideFlags=HideFlags.HideAndDontSave;}
