  void StartFacialFit(){Mesh currentHead=null;try{currentHead=RebirthFaceGeneratorModel.Build(template,recipe);facialFitJob=new RebirthNativeFacialFitJob(currentHead);status=facialFitJob.Status;}catch(Exception e){status=e.Message;}finally{if(currentHead!=null)DestroyImmediate(currentHead);}}
  void PollFacialFit(){if(facialFitJob==null)return;imageGenerationFailed=false;facialFitJob.Poll();lastProgress=facialFitJob.Progress;lastElapsed=facialFitJob.ElapsedSeconds;lastGeneration=facialFitJob.Status;status=facialFitJob.Status;if(facialFitJob.Finished){if(facialFitJob.Error==null){string guid=facialFitJob.ResultGuid;try{var trial=JsonUtility.FromJson<FaceNativeAppearanceSettings>(JsonUtility.ToJson(recipe.nativeAppearance));trial.facialAttachmentGuid=guid;var currentHead=RebirthFaceGeneratorModel.Build(template,recipe);try{using(var check=RebirthNativeAppearanceLibrary.Facial(currentHead,trial)){}}finally{DestroyImmediate(currentHead);}ChangeNative(()=>recipe.nativeAppearance.facialAttachmentGuid=guid,"Fit facial hair to head",true);}catch(Exception e){status=e.Message;lastGeneration=status;}}facialFitJob.Dispose();facialFitJob=null;}Repaint();}
