  public static string ImportHairComparison(string path,string referenceGuid){
   var report=JsonUtility.FromJson<RebirthReferenceHairMatcher.Report>(File.ReadAllText(path));
   if(report==null||report.scores==null||(report.scores.Length==0&&!report.insufficientSupport))throw new InvalidDataException("Empty hairstyle comparison.");
   if(report.observedHairColourAvailable)foreach(float value in new[]{report.observedHairColour.r,report.observedHairColour.g,report.observedHairColour.b})if(float.IsNaN(value)||float.IsInfinity(value)||value<0||value>1)throw new InvalidDataException("Invalid observed hair colour.");
   string reference=AssetDatabase.GUIDToAssetPath(referenceGuid);if(!File.Exists(reference))throw new FileNotFoundException("Select the comparison's reference image first.");
   string hash;using(var sha=System.Security.Cryptography.SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(reference))).Replace("-","").ToLowerInvariant();
   if(hash!=report.referenceSha256)throw new InvalidDataException("This comparison belongs to a different reference image.");
   if(!RebirthNativeAppearanceLibrary.Available||report.sourceHash!=RebirthNativeAppearanceLibrary.Catalog.sourceHash)throw new InvalidDataException("This comparison requires its matching game appearance library.");
   string source=Path.GetDirectoryName(Path.GetFullPath(path));
   foreach(var score in report.scores){if(string.IsNullOrEmpty(score.key))throw new InvalidDataException("Invalid hairstyle comparison key.");foreach(float value in new[]{score.rankScore,score.overlap,score.hairlineOverlap,score.appearanceClassCosine,score.appearancePatchCosine,score.belowEyeExtentDifference})if(float.IsNaN(value)||float.IsInfinity(value))throw new InvalidDataException("Invalid hairstyle comparison score.");if(score.extentAvailable&&score.belowEyeExtentDifference<0)throw new InvalidDataException("Invalid hairstyle extent difference.");if(RebirthNativeAppearanceLibrary.Style(score.key).family!="hair")throw new InvalidDataException("Comparison contains a facial-hair entry in head hair.");}
   foreach(var score in report.scores.Take(3))if(!string.IsNullOrEmpty(score.preview)&&(Path.GetFileName(score.preview)!=score.preview||Path.GetExtension(score.preview).ToLowerInvariant()!=".png"||!File.Exists(Path.Combine(source,score.preview))))throw new InvalidDataException("Invalid comparison preview.");
   string folder="Assets/HairComparison_"+Guid.NewGuid().ToString("N");AssetDatabase.CreateFolder("Assets",Path.GetFileName(folder));
   foreach(var score in report.scores.Take(3))if(!string.IsNullOrEmpty(score.preview))File.Copy(Path.Combine(source,score.preview),folder+"/"+score.preview);
   File.WriteAllText(folder+"/HairMatchReport.json",JsonUtility.ToJson(report,true));foreach(var score in report.scores.Take(3))if(!string.IsNullOrEmpty(score.preview))AssetDatabase.ImportAsset(folder+"/"+score.preview,ImportAssetOptions.ForceSynchronousImport);AssetDatabase.ImportAsset(folder+"/HairMatchReport.json",ImportAssetOptions.ForceSynchronousImport);return AssetDatabase.AssetPathToGUID(folder+"/HairMatchReport.json");
  }
