   if(preview==null)preview=new PreviewRenderUtility();
   preview.BeginPreview(new Rect(0,0,Mathf.Min(2560,rect.width*2),Mathf.Min(2560,rect.height*2)),GUIStyle.none);ConfigurePreview(preview,orbit,zoom,raking,recipe,framedAll?(Vector3?)viewCenter:null);RebirthPreviewAntialiasing.Configure(preview,!recipe.nativeAppearance.enabled&&RebirthHairGenerator.HasHair(recipe));if(recipe.nativeAppearance.enabled)preview.ambientColor=Color.white*previewAmbient;using(var lighting=recipe.nativeAppearance.enabled?new RebirthNativePreviewLighting(preview,previewReflections):null){RebirthNativePreviewLighting.Draw(preview,mesh,Matrix4x4.identity,material,0);RebirthNativePreviewLighting.Draw(preview,mesh,Matrix4x4.identity,eyeMaterial,1);if(oralMaterials==null)oralMaterials=CreateOralMaterials(recipe);DrawOral(preview,mesh,oralMaterials);DrawHair(preview,hairMesh,hairMaterials);RebirthFacialHairGenerator.Draw(preview,facialHair);preview.Render();GUI.DrawTexture(rect,preview.EndPreview(),ScaleMode.StretchToFill,false);}
  }
