  static string CopyReferenceHairReport(string guid,string folder){
   if(string.IsNullOrEmpty(guid))return "";string source=AssetDatabase.GUIDToAssetPath(guid);var asset=AssetDatabase.LoadAssetAtPath<TextAsset>(source);if(asset==null)throw new FileNotFoundException("The saved reference hairstyle report is missing.");
