   foreach(var candidate in report.scores??new RebirthReferenceHairMatcher.Score[0]){if(string.IsNullOrEmpty(candidate.preview))continue;if(Path.GetFileName(candidate.preview)!=candidate.preview)throw new InvalidDataException("Invalid reference hair preview path.");string input=sourceFolder+"/"+candidate.preview;if(!File.Exists(input)){candidate.preview=null;continue;}if(!AssetDatabase.CopyAsset(input,destination+"/"+candidate.preview))throw new IOException("Could not copy reference hair comparison image.");}
   string output=destination+"/HairMatchReport.json";File.WriteAllText(output,JsonUtility.ToJson(report,true));AssetDatabase.ImportAsset(output);return AssetDatabase.AssetPathToGUID(output);
  }
